ALTER TABLE warmup_identities ADD COLUMN profile_operation_status text CHECK(profile_operation_status IN('APPLYING','VERIFIED','UNKNOWN'));
ALTER TABLE warmup_identities ADD COLUMN profile_attempt_at timestamptz;
GRANT UPDATE(profile_operation_status,profile_attempt_at) ON warmup_identities TO commerce_channel;
CREATE TABLE operational_evidence(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id text NOT NULL,environment text NOT NULL CHECK(environment IN('REAL','SIMULATION')),kind text NOT NULL CHECK(kind IN('backup_external','restore_assets','smtp_received','alert_received','ai_evaluation','provider_capability','commercial_pilot','warmup_pilot','staging_24h','accessibility_human')),status text NOT NULL CHECK(status IN('VERIFIED','FAILED','UNAVAILABLE')),source text NOT NULL CHECK(source IN('HUMAN_ATTESTATION','SERVER_JOB')),evidence_ref text NOT NULL,details jsonb NOT NULL,observed_at timestamptz NOT NULL,expires_at timestamptz NOT NULL,actor_id text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TRIGGER immutable_operational_evidence BEFORE UPDATE OR DELETE ON operational_evidence FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE TABLE operational_alerts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id text NOT NULL,environment text NOT NULL CHECK(environment IN('REAL','SIMULATION')),dedupe_key text NOT NULL,kind text NOT NULL,severity text NOT NULL CHECK(severity IN('WARNING','CRITICAL')),summary_code text NOT NULL,status text NOT NULL DEFAULT 'PENDING' CHECK(status IN('PENDING','SENDING','ACCEPTED','RECEIVED','UNKNOWN','FAILED','RESOLVED')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,environment,dedupe_key));
GRANT SELECT ON operational_evidence,operational_alerts TO commerce_api,commerce_automation,commerce_channel,commerce_maintenance;
GRANT INSERT ON operational_evidence TO commerce_api,commerce_maintenance;
GRANT INSERT,UPDATE ON operational_alerts TO commerce_automation;
